insert into support_faq (question, answer) values
('Как пройти верификацию?', 'В профиле нажмите «Пройти верификацию» и загрузите фото документа, удостоверяющего личность. Проверка выполняется модератором вручную и обычно занимает до суток.'),
('Почему отклонили документ?', 'Причина указывается в статусе верификации в профиле. Чаще всего это нечитаемое фото, истёкший срок действия документа или несовпадение данных. Можно подать документ повторно.'),
('Почему отклонили объявление?', 'Причина показывается на экране объявления сразу после отклонения. Обычно это упоминание запрещённого товара, признаки мошенничества или контакты для связи в обход чата.'),
('Что означает статус сделки?', 'Статусы сделки идут по порядку: отклик → согласовано → передано курьеру → в пути → ожидает получения → доставлено → завершено. Каждый переход виден в чате сделки системным сообщением.'),
('Как продлить хранение посылки?', 'На экране сделки заказчик может запросить продление срока хранения. Курьер получает уведомление и подтверждает или отклоняет запрос.'),
('Что делать при перевесе?', 'Если фактический вес больше заявленного, цена пересчитывается автоматически, и обеим сторонам нужно заново подтвердить условия сделки в чате.'),
('Как удалить аккаунт?', 'В профиле внизу есть кнопка удаления аккаунта. Данные, необходимые для проверки безопасности (хеш номера документа), сохраняются даже после удаления — это защищает других пользователей.'),
('Почему нельзя опубликовать объявление без верификации?', 'Публикуют объявления и откликаются на них только проверенные пользователи — это защищает и курьеров, и заказчиков от мошенничества.'),
('Кто отвечает за содержимое посылки?', 'Ответственность за содержимое несёт заказчик. Курьер вправе отказаться от посылки, если её содержимое не соответствует описи или вызывает подозрения.'),
('Что делать, если посылку не забирают?', 'Если срок хранения истёк, а посылку не забрали, сделка автоматически помечается как проблемная и попадает на рассмотрение модератора.');
